<script lang="ts">
  import LengthInput from './LengthInput.svelte';
  import {usePlanningUnits} from '#lib/client/planning-units.svelte.ts';
  const units=usePlanningUnits();
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import type{DesignSnapshot,DesignOperation,WallElement}from'@schubert/contracts';
 import{connectedWallIds,parseMillimetres,applyOperations}from'@schubert/geometry';
 import{describeStudioIssue}from'./issues.ts';
 let{snapshot,wall,disabled=false,onchange}:{snapshot:DesignSnapshot;wall:WallElement;disabled?:boolean;onchange:(ops:DesignOperation[])=>void}=$props();
 const nodes=$derived(snapshot.elements.filter(e=>e.kind==='node'));
 const network=$derived(connectedWallIds(snapshot,wall.id));
 let dx=$state('0'),dy=$state('0'),dz=$state('0'),error=$state(''),splitDistance=$state(''),splitError=$state('');
 function translate(event:SubmitEvent){event.preventDefault();error='';try{const values=[dx,dy,dz].map(parseMillimetres);if(values.some(v=>v===null))throw Error('Alle drei Verschiebungen eindeutig in mm angeben.');const operations:DesignOperation[]=[{type:'move_element',elementId:wall.id,delta:{xMm:values[0]!,yMm:values[1]!,zMm:values[2]!}}];applyOperations(snapshot,operations);onchange(operations);dx='0';dy='0';dz='0';}catch(problem){error=describeStudioIssue(snapshot,(problem as Error).message).message;}}
 function split(event:SubmitEvent){event.preventDefault();splitError='';try{const distance=parseMillimetres(splitDistance);if(distance===null)throw Error('Den Abstand vom Wandanfang eindeutig in mm angeben.');const operation:DesignOperation={type:'split_wall',elementId:wall.id,newNodeId:crypto.randomUUID(),newWallId:crypto.randomUUID(),distanceMm:distance};applyOperations(snapshot,[operation]);onchange([operation]);splitDistance='';}catch(problem){splitError=describeStudioIssue(snapshot,(problem as Error).message).message;}}
</script>
<div class="wall-geometry"><h3>Gemeinsame Knoten & Anschluss</h3><p>Nur ausdrücklich gemeinsam referenzierte Knoten bilden einen Anschluss. Deckungsgleiche getrennte Punkte bleiben getrennte Bezüge.</p>
 <form onsubmit={translate}><h3>Wand gemeinsam versetzen</h3><p>Verschiebt beide Wandknoten in einem Schritt. Gebundene Öffnungen und angrenzende Räume verwenden weiterhin dieselben Bezüge. Die Werte gelten im Bezugssystem der Wand.</p><div class="delta-fields"><label>Versatz X ({units.unit})<LengthInput inputmode="decimal" bind:value={dx} required {disabled}/></label><label>Versatz Y ({units.unit})<LengthInput inputmode="decimal" bind:value={dy} required {disabled}/></label><label>Versatz Z ({units.unit})<LengthInput inputmode="decimal" bind:value={dz} required {disabled}/></label></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<button class="btn small" type="submit" {disabled}>Wand um diese Werte versetzen</button></form>
 <form onsubmit={split}><h3>Einen gemeinsamen Anschlussknoten anlegen</h3><p>Teilt die Wand innerhalb ihrer Achse in zwei Teile. Räume und eindeutig zuordenbare Öffnungen behalten ihre Bezüge. Eine Öffnung darf dabei nicht durchschnitten werden. Den neuen Knoten können weitere Wände gemeinsam verwenden.</p><label>Teilungsabstand vom Wandanfang ({units.unit})<LengthInput class="split-distance" inputmode="decimal" bind:value={splitDistance} required {disabled}/></label>{#if splitError}<p class="error" role="alert">{splitError}</p>{/if}<button class="btn small" type="submit" {disabled}>Wand an diesem Punkt teilen</button></form>
 <label>Anfangsknoten<select use:searchableSelect={wall.startNodeId} value={wall.startNodeId} onchange={event=>onchange([{type:'set_wall',elementId:wall.id,startNodeId:event.currentTarget.value}])} {disabled}>{#each nodes as node}<option value={node.id}>{node.label} · {node.point.xMm} / {node.point.yMm} / {node.point.zMm} mm</option>{/each}</select></label>
 <label>Endknoten<select use:searchableSelect={wall.endNodeId} value={wall.endNodeId} onchange={event=>onchange([{type:'set_wall',elementId:wall.id,endNodeId:event.currentTarget.value}])} {disabled}>{#each nodes as node}<option value={node.id}>{node.label} · {node.point.xMm} / {node.point.yMm} / {node.point.zMm} mm</option>{/each}</select></label>
 <label>Geometrischer Kernanschluss<select use:searchableSelect={wall.joinStyle??'legacy_overlap'} value={wall.joinStyle??'legacy_overlap'} onchange={event=>onchange([{type:'set_wall',elementId:wall.id,joinStyle:event.currentTarget.value as 'miter'|'legacy_overlap'}])} {disabled}><option value="miter">Geometrische Gehrung an gemeinsamen Knoten</option><option value="legacy_overlap">Überlappung am Achsknoten</option></select></label><p>Die Gehrung berücksichtigt auch schräge und T-förmige Anschlüsse. Schichten folgen der Anschlussfläche. Das bestätigt keine Statik, Abdichtung, Befestigung oder Montagefreigabe.</p>
 {#if network.length>1}<button class="btn small" type="button" onclick={()=>onchange(network.map(elementId=>({type:'set_wall',elementId,joinStyle:wall.joinStyle??'legacy_overlap'})))} {disabled}>Anschluss auf {network.length} verbundene Wände übertragen</button><p>Übernimmt ausdrücklich die oben gewählte Anschlussart für das angezeigte Wandnetz. Gesperrte Elemente werden dabei nicht umgangen; die gesamte Änderung lässt sich rückgängig machen.</p>{/if}
</div>

<style>:global(.split-distance){box-sizing:border-box;display:block;width:100%;min-height:44px;padding:10px;margin-top:7px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);font:inherit;font-size:14px}@media(max-width:720px){:global(.split-distance){min-height:48px;font-size:16px}}.wall-geometry{font-size:13px;line-height:1.65;margin-top:20px;border-top:1px solid var(--line);padding-top:16px}.wall-geometry h3{font-size:14px;font-weight:600}.wall-geometry p{font-size:12px;color:var(--muted)}.wall-geometry label{display:block;margin:16px 0;font-size:13px}.wall-geometry select{display:block;box-sizing:border-box;width:100%;font:inherit;font-size:14px;padding:10px;border:1px solid var(--line);border-radius:4px;background:var(--paper);color:var(--ink);min-height:44px;margin-top:7px}@media(max-width:720px){.wall-geometry select{font-size:16px;min-height:48px}}.delta-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.delta-fields :global(input){display:block;box-sizing:border-box;width:100%;min-height:44px;margin-top:7px;padding:10px;border:1px solid var(--line);border-radius:4px;font:inherit;font-size:14px;background:var(--paper);color:var(--ink)}.error{white-space:pre-wrap;background:var(--danger-wash);color:var(--danger);padding:12px;border:1px solid var(--line)}form{padding-bottom:20px;border-bottom:1px solid var(--line);margin-bottom:18px}@media(max-width:720px){.delta-fields :global(input){min-height:48px;font-size:16px}} </style>
